def transform(grid):
    """Continue each diagonal line of at least two adjacent same-colored cells.

    Extend both ends through the background, stopping at an edge or another
    non-background cell.
    """
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    # A diagonal pair determines a line. Extend its two ends, preserving all
    # existing cells and stopping at any non-background cell.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if not (0 <= nr < h and 0 <= nc < w) or grid[nr][nc] != color:
                    continue
                # Extend backward from the first cell and forward from the second.
                for rr, cc, sr, sc in ((r - dr, c - dc, -dr, -dc),
                                       (nr + dr, nc + dc, dr, dc)):
                    while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                        out[rr][cc] = color
                        rr += sr
                        cc += sc
    return out

